#[test]
fn converted_scope_shadowing_inside_block() {
    let value = run("(let x 1) ((let x 2) x)").unwrap();
    assert!(equals(&value, &Value::Int(2)));
}

#[test]
fn converted_scope_mutation_inside_block() {
    let value = run("(let x 1) ((let x 2) (set x 3) x)").unwrap();
    assert!(equals(&value, &Value::Int(3)));
}

#[test]
fn converted_loop_scope_preserves_outer_binding() {
    let value = run("(let x 10) ((loop (let y 42) (break y))) x").unwrap();
    assert!(equals(&value, &Value::Int(10)));
}

#[test]
fn converted_nested_scope_inner_binding() {
    let value = run("(let x 1) ((let x 2) ((let x 3) x) x) x").unwrap();
    assert!(equals(&value, &Value::Int(1)));
}

#[test]
fn converted_nested_scope_middle_binding() {
    let value = run("(let x 1) ((let x 2) ((let x 3) x) x)").unwrap();
    assert!(equals(&value, &Value::Int(2)));
}

#[test]
fn converted_nested_scope_inner_value() {
    let value = run("(let x 1) ((let x 2) ((let x 3) x))").unwrap();
    assert!(equals(&value, &Value::Int(3)));
}
